def _chat_json(self, prompt: str, attempts: int = 3) -> dict | None:
    """Send one text-only prompt; return a parsed JSON object or None.

    On a non-JSON reply we return ``{"_raw_text": <reply>}`` so callers can
    still salvage prose.
    """
    if not self.available:
        return None

    delay = 1.0
    for attempt in range(1, attempts + 1):
        try:
            resp = self.client.chat.completions.create(
                model=self.model,
                messages=[{"role": "user", "content": prompt}],
                temperature=0.2,
            )
            text = resp.choices[0].message.content or ""
            parsed = _parse_llm_json(text)
            if parsed:
                return parsed
            if text.strip():
                return {"_raw_text": text.strip()}
            raise ValueError("empty response")
        except Exception as exc:
            if attempt < attempts:
                time.sleep(delay)
                delay *= 2
            else:
                print(
                    f"[warn] LLM request failed ({exc}); using fallback.",
                    file=sys.stderr,
                )
    return None

def _request_explanation(
    self,
    prompt: str,
    default_steps: list[str],
    attempts: int = 3,
) -> dict | None:
    """Send one text-only prompt and normalise a {reasoning, steps} reply."""
    parsed = self._chat_json(prompt, attempts)
    if not parsed:
        return None
    reasoning = parsed.get("reasoning") or parsed.get("_raw_text")
    if not reasoning:
        return None
    steps = parsed.get("solution_steps") or []
    if not isinstance(steps, list):
        steps = [str(steps)]
    steps = [str(s).strip() for s in steps if str(s).strip()]
    return {
        "reasoning": str(reasoning).strip(),
        "solution_steps": steps or list(default_steps),
    }

