# ---------------------------------------------------------------------------
# Function convexity (numeric curvature probe; GPT-4o is the primary engine)
# ---------------------------------------------------------------------------
_CONVEXITY_NS = {"log": math.log, "exp": math.exp, "abs": abs, "Abs": abs}


def _compile_convexity_function(code: str):
    """Turn ``'f(x) = ...'`` into a callable of ``x`` using the math names."""
    expr = code.split("=", 1)[-1].strip()
    return lambda x: eval(expr, {"__builtins__": {}}, {**_CONVEXITY_NS, "x": x})


def _convexity_sample_points(domain) -> list[float]:
    if domain and "x > 0" in str(domain):
        return [0.05, 0.1, 0.2, 0.35, 0.5, 0.75, 1.0, 1.3, 1.6, 2.0, 2.5, 3.0]
    return [0.0, -3.0, -2.5, -2.0, -1.6, -1.3, -1.0, -0.7, -0.5, -0.35,
            -0.2, -0.1, 0.1, 0.2, 0.35, 0.5, 0.75, 1.0, 1.3, 1.6, 2.0, 2.5, 3.0]


def numeric_convexity_probe(code: str, domain) -> dict:
    """Light-weight numeric curvature check via central second differences.

    Returns ``{"label", "samples", "summary", "confident"}``. The label is used
    as a computational cross-check and as a fallback when GPT-4o is
    unavailable; per the task, GPT-4o decides the final label.
    """
    try:
        f = _compile_convexity_function(code)
    except Exception:
        return {"label": "neither", "samples": [], "confident": False,
                "summary": "could not parse the function"}

    samples = []
    for x in _convexity_sample_points(domain):
        h = max(1e-3, abs(x) * 1e-3)
        try:
            value = (f(x + h) - 2.0 * f(x) + f(x - h)) / (h * h)
        except Exception:
            continue
        if math.isfinite(value):
            samples.append((x, value))

    if not samples:
        return {"label": "neither", "samples": [], "confident": False,
                "summary": "no valid sample points"}

    scale = max(1.0, max(abs(v) for _, v in samples))
    tol = 1e-6 * scale
    convex = all(v >= -tol for _, v in samples)
    concave = all(v <= tol for _, v in samples)
    if convex:
        # An affine function satisfies both; default to convex.
        label = "convex"
    elif concave:
        label = "concave"
    else:
        label = "neither"

    def sign(v: float) -> str:
        if v > tol:
            return "+"
        if v < -tol:
            return "-"
        return "0"

    shown = ", ".join(f"x={x:g}:{sign(v)}" for x, v in samples)
    summary = (
        f"sampled signs of f''(x) were {{{shown}}}, which suggests the "
        f"function is {label} on its domain"
    )
    return {
        "label": label,
        "samples": samples,
        "summary": summary,
        "confident": label != "neither",
    }


def fallback_convexity_explanation(problem: dict, numeric: dict) -> dict:
    """Deterministic convexity explanation used when no LLM is available."""
    label = numeric["label"]
    domain = problem.get("domain") or "all real x"
    curvature = {
        "convex": "nonnegative (f''(x) >= 0)",
        "concave": "nonpositive (f''(x) <= 0)",
        "neither": "of changing sign",
    }.get(label, "of changing sign")
    reasoning = (
        f"Estimated the second derivative numerically over the domain "
        f"({domain}). At the sampled points the curvature is {curvature}, so "
        f"the function is {label}."
    )
    return {
        "answer": label,
        "reasoning": reasoning,
        "solution_steps": _default_convexity_steps(),
        "confidence": 0.9 if numeric.get("confident") else 0.7,
    }


def build_convexity_fewshot(
    limit: int = CONVEXITY_FEWSHOT_COUNT,
) -> list[dict]:
    """Select a small, diverse, label-balanced subset of develop examples.

    Examples are bucketed by (domain, presence of log/Abs/exp, label) so the
    few-shot prompt covers the different function families, then a
    representative is taken from each bucket (both labels guaranteed).
    """
    problems = discover_problems(CONVEXITY_DEVELOP_SPLIT)
    buckets: dict[tuple, list[dict]] = defaultdict(list)
    for p in problems:
        if "label" not in p:
            continue
        key = [secret redacted]
            str(p.get("domain")),
            "log(" in p["code"],
            "Abs(" in p["code"],
            "exp(" in p["code"]),
            p["label"],
        )
        buckets[key].append(p)

    representatives = [items[0] for _, items in sorted(buckets.items())]
    selected: list[dict] = []
    for want in ("convex", "concave", "neither"):
        for rep in representatives:
            if rep["label"] == want and rep not in selected:
                selected.append(rep)
                break
    for rep in representatives:
        if len(selected) >= limit:
            break
        if rep not in selected:
            selected.append(rep)

    return [
        {
            "domain": p.get("domain"),
            "latex": p.get("latex", ""),
            "code": p["code"],
            "label": p["label"],
        }
        for p in selected[:limit]
    ]

    return {
        "name": "graph_maxflow",
        "test_split": MAXFLOW_TEST_SPLIT,
        "confidence": MAXFLOW_CONFIDENCE,
        "solve": solve,
        "coerce": int,
        "llm": via_llm,
        "fallback": fallback_maxflow_explanation,
    }


def _convexity_task() -> dict:
    examples = build_convexity_fewshot()
    print(f"[info] Loaded {len(examples)} few-shot convexity examples from develop.")

    def via_llm(client, p, numeric):
        return client.llm_explain_convexity(p, numeric, examples)

    return {
        "name": "math_convexity",
        "test_split": CONVEXITY_TEST_SPLIT,
