def build_convexity_fewshot(
    limit: int = CONVEXITY_FEWSHOT_COUNT,
) -> list[dict]:
    """Select a small, diverse, label-balanced subset of develop examples.

    Problems are bucketed by (domain, presence of log/Abs/exp, label) so each
    distinct function family contributes at most one representative; the
    representatives are then interleaved across the ``x > 0`` and "all reals"
    domains and across the two labels, giving a prompt that covers both domains
    and both answers.
    """
    problems = discover_problems(CONVEXITY_DEVELOP_SPLIT)
    buckets: dict[tuple, list[dict]] = defaultdict(list)
    for p in problems:
        if "label" not in p:
            continue
        key = [secret redacted]
            str(p.get("domain")),
            "log(" in p["code"],
            "Abs(" in p["code"],
            "exp(" in p["code"],
            p["label"],
        )
        buckets[key].append(p)

    representatives = [items[0] for _, items in sorted(buckets.items())]

    def is_positive_domain(p: dict) -> bool:
        return bool(p.get("domain")) and "x > 0" in str(p["domain"])

    def interleave_labels(pool: list[dict]) -> list[dict]:
        by_label: dict[str, list[dict]] = defaultdict(list)
        for r in pool:
            by_label[r["label"]].append(r)
        labels = [lbl for lbl in ("convex", "concave", "neither") if by_label[lbl]]
        ordered: list[dict] = []
        index = 0
        while any(index < len(by_label[lbl]) for lbl in labels):
            for lbl in labels:
                if index < len(by_label[lbl]):
                    ordered.append(by_label[lbl][index])
            index += 1
        return ordered

    real_pool = interleave_labels(
        [r for r in representatives if not is_positive_domain(r)]
    )
    pos_pool = interleave_labels(
        [r for r in representatives if is_positive_domain(r)]
    )

    selected: list[dict] = []
    i = j = 0
    turn = 0  # alternate domains so both appear even when one pool is larger
    while len(selected) < limit and (i < len(real_pool) or j < len(pos_pool)):
        if turn == 0 and i < len(real_pool):
            selected.append(real_pool[i])
            i += 1
        elif turn == 1 and j < len(pos_pool):
            selected.append(pos_pool[j])
            j += 1
        elif i < len(real_pool):
            selected.append(real_pool[i])
            i += 1
        elif j < len(pos_pool):
            selected.append(pos_pool[j])
            j += 1
        turn ^= 1

    return [
        {
            "domain": p.get("domain"),
            "latex": p.get("latex", ""),
            "code": p["code"],
            "label": p["label"],
        }
        for p in selected[:limit]
    ]

