# ---------------------------------------------------------------------------
# Subtask 5: budgets, voting and per-mode reasoning strategies
# ---------------------------------------------------------------------------
def _with_budget(fn, seconds: float):
    """Run ``fn`` with a wall-clock timeout; return its result or None.

    Enforces the per-problem time budget. If the budget is exceeded the caller
    falls back to a low-confidence answer so one slow instance cannot stall the
    whole run.
    """
    if seconds is None or seconds <= 0:
        return fn()
    with ThreadPoolExecutor(max_workers=1) as pool:
        future = pool.submit(fn)
        try:
            return future.result(timeout=seconds)
        except FutureTimeout:
            print(
                f"[warn] per-problem budget of {seconds:.0f}s exceeded; "
                f"falling back.",
                file=sys.stderr,
            )
            return None


def _majority_vote(results: list[dict], key: str = "answer"):
    """Majority vote over sampled answers, tie-broken by summed confidence."""
    counts = Counter(r.get(key) for r in results if r.get(key) is not None)
    if not counts:
        return None
    best = max(counts.values())
    winners = [answer for answer, n in counts.items() if n == best]
    if len(winners) == 1:
        return winners[0]
    confidence_sums = {answer: 0.0 for answer in winners}
    for r in results:
        answer = r.get(key)
        if answer in confidence_sums:
            try:
                confidence_sums[answer] += float(r.get("confidence", 0.5))
            except (TypeError, ValueError):
                confidence_sums[answer] += 0.5
    return max(confidence_sums, key=[secret redacted]


def _merge_votes(results: list[dict], winner, strategy: str) -> dict:
    """Pick a representative sample for the winning answer and set confidence."""
    chosen = next((r for r in results if r.get("answer") == winner), results[0])
    merged = dict(chosen)
    winner_confs = [
        float(r.get("confidence", 0.7))
        for r in results
        if r.get("answer") == winner and _is_number(r.get("confidence"))
    ]
    if winner_confs:
        merged["confidence"] = max(0.0, min(1.0, max(winner_confs)))
    merged["_strategy"] = strategy
    return merged


def _is_number(value) -> bool:
    try:
        float(value)
        return True
    except (TypeError, ValueError):
        return False


def _convexity_confident(sample: dict, numeric: dict) -> bool:
    return (
        sample.get("answer") == numeric.get("label")
        and _is_number(sample.get("confidence"))
        and float(sample["confidence"]) >= CONVEXITY_CONFIDENCE_THRESHOLD
    )


# --- graph strategies (algorithmic answer; LLM only writes the explanation) --
def _strategy_connectivity(client, problem, solver_output, mode, cfg):
    got = client.llm_explain_connectivity(
        problem, solver_output, temperature=cfg.get("temperature", 0.2)
    )
    return got, 1, "single_call"


def _strategy_maxflow(client, problem, solver_output, mode, cfg):
    _, paths = edmonds_karp(
        problem["adjacency_matrix"], problem["source_node"], problem["sink_node"]
    )
    got = client.llm_explain_maxflow(
        problem, solver_output, paths, temperature=cfg.get("temperature", 0.2)
    )
    return got, 1, "single_call"


