def _strategy_convexity(client, problem, solver_output, mode, cfg):
    numeric = solver_output
    examples = cfg.get("_examples") or build_convexity_fewshot()
    base_temp = float(cfg.get("temperature", 0.2))
    samples = max(1, int(cfg.get("samples", 1)))
    adaptive = bool(cfg.get("adaptive", False))

    results: list[dict] = []
    calls = 0
    for i in range(samples):
        temp = base_temp if not adaptive else min(1.0, base_temp + 0.15 * i)
        got = client.llm_explain_convexity(
            problem, numeric, examples, temperature=temp
        )
        calls += 1
        if got:
            results.append(got)
            if adaptive and _convexity_confident(got, numeric):
                break  # confident first sample: no need to sample more

    if not results:
        return None, calls, "failed_all_samples"
    if len(results) == 1:
        return results[0], calls, "single_call"
    winner = _majority_vote(results)
    strategy = f"adaptive_{calls}_calls" if adaptive else f"self_consistency_{calls}_votes"
    return _merge_votes(results, winner, strategy), calls, strategy


# --- geometry strategy (self-consistency / adaptive) ------------------------
def _strategy_geometry(client, problem, solver_output, mode, cfg):
    base_temp = float(cfg.get("temperature", 0.2))
    samples = max(1, int(cfg.get("samples", 1)))
    adaptive = bool(cfg.get("adaptive", False))

    results: list[dict] = []
    calls = 0
    for i in range(samples):
        temp = base_temp if not adaptive else min(1.0, base_temp + 0.15 * i)
        got = solve_geometry_with_llm(
            problem.get("image_path"), problem, client, temperature=temp
        )
        calls += 1
        if got:
            results.append(got)
            if (
                adaptive
                and _is_number(got.get("confidence"))
                and float(got["confidence"]) >= GEOMETRY_CONFIDENCE_THRESHOLD
            ):
                break
    if not results:
        return None, calls, "failed_all_samples"
    if len(results) == 1:
        return results[0], calls, "single_call"
    winner = _majority_vote(results)
    strategy = f"adaptive_{calls}_calls" if adaptive else f"self_consistency_{calls}_votes"
    return _merge_votes(results, winner, strategy), calls, strategy


# ---------------------------------------------------------------------------
# Subtask 5: calibration on the develop split
# ---------------------------------------------------------------------------
def _spread(items: list, k: int) -> list:
    """Deterministically pick ``k`` evenly spaced items."""
    if k <= 0 or len(items) <= k:
        return list(items)
    step = len(items) / k
    return [items[int(i * step)] for i in range(k)]


def _write_debug(name: str, payload: dict) -> None:
    try:
        write_json(OUTPUTS_DIR / "debug" / name, payload)
    except Exception as exc:  # never let logging break the run
        print(f"[warn] could not write debug artifact {name}: {exc}", file=sys.stderr)


def _calibrate_geometry(client, mode) -> tuple[dict, dict]:
    """Evaluate candidate geometry strategies on a develop subset."""
    problems = discover_geometry_problems(GEOMETRY_DEVELOP_SPLIT)
    subset = _spread(problems, CALIBRATION_GEOMETRY_SUBSET)
    candidates = [
        {"label": "single_temp0.2", "samples": 1, "temperature": 0.2, "adaptive": False},
        {"label": "self_consistency3_temp0.7", "samples": 3,
         "temperature": 0.7, "adaptive": False},
    ]
    if mode == "improved2":
        candidates.append({"label": "adaptive3_temp0.7", "samples": 3,
                           "temperature": 0.7, "adaptive": True})

    reports = []
    for cand in candidates:
        correct = 0
        calls = 0
        for p in subset:
            votes = []
            for i in range(cand["samples"]):
                temp = (
                    cand["temperature"]
                    if not cand["adaptive"]
                    else min(1.0, cand["temperature"] + 0.15 * i)
                )
                got = solve_geometry_with_llm(
                    p.get("image_path"), p, client, temperature=temp
                )
                calls += 1
                if got:
                    votes.append(got)
                    if (
                        cand["adaptive"]
                        and _is_number(got.get("confidence"))
                        and float(got["confidence"]) >= GEOMETRY_CONFIDENCE_THRESHOLD
                    ):
                        break
            if votes:
                answer = _majority_vote(votes) if len(votes) > 1 else votes[0]["answer"]
                if answer == p.get("answer"):
                    correct += 1
        reports.append({
            **cand,
            "accuracy": round(correct / max(1, len(subset)), 4),
            "llm_calls": calls,
        })

    best = max(reports, key=lambda r: (r["accuracy"], -r["llm_calls"]))
    chosen = {
        "samples": best["samples"],
        "temperature": best["temperature"],
        "adaptive": best["adaptive"],
    }
    return chosen, {
        "subset_size": len(subset),
        "candidates": reports,
        "selected": best["label"],
    }


def _calibrate_convexity(client, mode) -> tuple[dict, dict]:
    """Evaluate candidate convexity strategies on a develop subset."""
    problems = discover_problems(CONVEXITY_DEVELOP_SPLIT)
    subset = _spread(problems, CALIBRATION_CONVEXITY_SUBSET)
    examples = build_convexity_fewshot()
    candidates = [
        {"label": "single_temp0.2", "samples": 1, "temperature": 0.2, "adaptive": False},
        {"label": "self_consistency3_temp0.7", "samples": 3,
         "temperature": 0.7, "adaptive": False},
    ]
    if mode == "improved2":
        candidates.append({"label": "adaptive3_temp0.7", "samples": 3,
                           "temperature": 0.7, "adaptive": True})

    reports = []
    for cand in candidates:
        correct = 0
        calls = 0
        for p in subset:
            numeric = numeric_convexity_probe(p["code"], p.get("domain"))
            votes = []
            for i in range(cand["samples"]):
                temp = (
                    cand["temperature"]
                    if not cand["adaptive"]
                    else min(1.0, cand["temperature"] + 0.15 * i)
                )
                got = client.llm_explain_convexity(
                    p, numeric, examples, temperature=temp
                )
                calls += 1
                if got:
                    votes.append(got)
                    if cand["adaptive"] and _convexity_confident(got, numeric):
                        break
            if votes:
                answer = _majority_vote(votes) if len(votes) > 1 else votes[0]["answer"]
                if answer == p.get("label"):
                    correct += 1
        reports.append({
            **cand,
            "accuracy": round(correct / max(1, len(subset)), 4),
            "llm_calls": calls,
        })

    best = max(reports, key=lambda r: (r["accuracy"], -r["llm_calls"]))
    chosen = {
