        "selected": best["label"],
    }


def calibrate(mode: str, client) -> dict:
    """Select strategy parameters using the develop split.

    Called for every mode; for ``improved1``/``improved2`` it evaluates prompt /
    sampling candidates on a develop subset and returns the best configuration,
    which then drives test-time behaviour. Graph tasks are confirmed to be
    exact. Artifacts are written under ``outputs/debug/`` (never mixed into the
    main ``outputs/<task>/`` results).
    """
    defaults = MODE_DEFAULTS[mode]
    config = {
        "graph_connectivity": {"temperature": 0.2},
        "graph_maxflow": {"temperature": 0.2},
        "geometry": dict(defaults),
        "math_convexity": dict(defaults),
    }
    report = {"mode": mode, "generated_at": time.strftime("%Y-%m-%dT%H:%M:%S")}

    # Graph tasks: confirm the exact solvers are perfect on develop.
    for name, split, solver in (
        ("graph_connectivity", DEVELOP_SPLIT,
         lambda p: is_connected(
             p["adjacency_matrix"], p["query_node_1"], p["query_node_2"])),
        ("graph_maxflow", MAXFLOW_DEVELOP_SPLIT,
         lambda p: edmonds_karp(
             p["adjacency_matrix"], p["source_node"], p["sink_node"])[0]),
    ):
        problems = discover_problems(split)
        bad = sum(
            1 for p in problems if "label" in p and solver(p) != p["label"]
        )
        report[name] = {
            "develop_total": len(problems),
            "develop_mismatches": bad,
            "develop_accuracy": round(
                (len(problems) - bad) / max(1, len(problems)), 4
            ),
        }

    if mode == "baseline":
        report["skipped"] = True
        report["reason"] = "baseline uses a single deterministic call per problem"
        _write_debug(f"calibration_{mode}.json", report)
        return config

    if client is None or not client.available:
        report["skipped"] = True
        report["reason"] = "no LLM available; using mode defaults"
        _write_debug(f"calibration_{mode}.json", report)
        print(
            f"[info] Calibration ({mode}) skipped: no LLM; using mode defaults."
        )
        return config

    print(f"[info] Calibrating geometry + convexity strategies for mode '{mode}'...")
    geo_cfg, geo_report = _calibrate_geometry(client, mode)
    conv_cfg, conv_report = _calibrate_convexity(client, mode)
    config["geometry"] = geo_cfg
    config["math_convexity"] = conv_cfg
    report["geometry"] = geo_report
    report["math_convexity"] = conv_report
    report["skipped"] = False
    _write_debug(f"calibration_{mode}.json", report)
    print(
        f"[info] Calibration selected geometry={geo_report['selected']} "
        f"(acc {geo_report['candidates'][-1]['accuracy']}), "
        f"convexity={conv_report['selected']}."
    )
    return config

