    def solve(p):
        value, _ = edmonds_karp(
            p["adjacency_matrix"], p["source_node"], p["sink_node"]
        )
        return value

    def via_llm(client, p, ans):
        _, paths = edmonds_karp(
            p["adjacency_matrix"], p["source_node"], p["sink_node"]
        )
        return client.llm_explain_maxflow(p, ans, paths)

    return {
        "name": "graph_maxflow",
        "test_split": MAXFLOW_TEST_SPLIT,
        "confidence": MAXFLOW_CONFIDENCE,
        "solve": solve,
        "coerce": int,
        "llm": via_llm,
        "fallback": fallback_maxflow_explanation,
    }


def _convexity_task() -> dict:
    examples = build_convexity_fewshot()
    print(f"[info] Loaded {len(examples)} few-shot convexity examples from develop.")

    def via_llm(client, p, numeric):
        got = client.llm_explain_convexity(p, numeric, examples)
